para.example:
   goto को उदाहरण


<?php
goto a;
echo 'Foo';

a:
echo 'Bar';
?>


   &example.outputs;


Bar

   goto loop को उदाहरण


<?php
for ($i = 0, $j = 50; $i < 100; $i++) {
    while ($j--) {
        if ($j == 17) {
            goto end;
        }
    }
}
echo "i = $i";
end:
echo 'j hit 17';
?>


   &example.outputs;


j hit 17

   यसले काम गर्दैन


<?php
goto loop;
for ($i = 0, $j = 50; $i < 100; $i++) {
    while ($j--) {
        loop:
    }
}
echo "$i = $i";
?>


   &example.outputs.similar;


Fatal error: 'goto' into loop or switch statement is disallowed in script on line 2
